-- Barber PIN sign-in (no more e-mail invitations) + admin recovery key.
--
-- Fahru's request (2026-10-12):
--   * "Admin just assign barber name in the panel. No more invitation."
--     Admin types a barber's name and a 6-digit PIN; the barber signs in by
--     picking his name and entering the PIN. No e-mail is ever sent.
--   * "Admin able to reset the website with keys if lockout."
--     A one-time recovery key, generated by an admin and kept offline, lets a
--     locked-out admin set a new password (and reactivates the account).
--
-- Every staff member is still a Supabase Auth user (auth.uid() drives every
-- seat/queue permission). A barber's account gets a synthetic e-mail and a
-- long random password nobody knows; the barber-login Edge Function checks
-- the PIN here, then rotates that password and signs in server-side. So the
-- 6-digit PIN is never usable against Supabase's own sign-in endpoint, and
-- its attempts are counted and locked here.
--
-- Secrets are stored only as bcrypt hashes (pgcrypto crypt()). The tables
-- below have RLS on with no policies and no grants: only SECURITY DEFINER
-- functions, and the service_role used by the Edge Functions, can touch them.
-- pgcrypto lives in `extensions` on the hosted project, hence the
-- search_path on every function here.

-- 1. state ---------------------------------------------------------------
create table public.staff_pins (
    staff_id        uuid primary key references public.staff (id) on delete cascade,
    pin_hash        text not null,
    failed_attempts integer not null default 0,
    locked_until    timestamptz,
    updated_at      timestamptz not null default now()
);
alter table public.staff_pins enable row level security;
revoke all on public.staff_pins from public, anon, authenticated;
-- Explicit deny-all: no direct client access, ever (functions below only).
create policy "no direct access to staff pins" on public.staff_pins
    for all to anon, authenticated using (false) with check (false);

create table public.admin_recovery (
    id              boolean primary key default true check (id),
    key_hash        text,
    created_at      timestamptz,
    created_by      uuid references public.staff (id) on delete set null,
    failed_attempts integer not null default 0,
    locked_until    timestamptz
);
alter table public.admin_recovery enable row level security;
revoke all on public.admin_recovery from public, anon, authenticated;
create policy "no direct access to admin recovery" on public.admin_recovery
    for all to anon, authenticated using (false) with check (false);
insert into public.admin_recovery (id) values (true) on conflict do nothing;

-- 2. admin sets a barber's PIN --------------------------------------------
create or replace function public.admin_set_barber_pin(p_staff_id uuid, p_pin text)
returns void language plpgsql security definer set search_path = public, extensions as $$
begin
    if not public.is_admin() then
        raise exception 'Not authorised' using errcode = '42501';
    end if;
    if p_pin is null or p_pin !~ '^[0-9]{6}$' then
        raise exception 'PIN mesti 6 digit nombor.' using errcode = '22023';
    end if;
    if p_pin ~ '^(.)\1{5}$' or p_pin in ('123456', '654321', '012345', '543210') then
        raise exception 'PIN terlalu mudah diteka. Pilih PIN lain.' using errcode = '22023';
    end if;
    if not exists (select 1 from public.staff where id = p_staff_id and role = 'barber') then
        raise exception 'Tukang gunting tidak ditemui.' using errcode = 'P0002';
    end if;

    insert into public.staff_pins (staff_id, pin_hash, failed_attempts, locked_until, updated_at)
    values (p_staff_id, crypt(p_pin, gen_salt('bf', 10)), 0, null, now())
    on conflict (staff_id) do update
        set pin_hash = excluded.pin_hash, failed_attempts = 0, locked_until = null, updated_at = now();
end $$;

revoke all on function public.admin_set_barber_pin(uuid, text) from public, anon;
grant execute on function public.admin_set_barber_pin(uuid, text) to authenticated;

-- 3. sign-in screen: which barbers can sign in ------------------------------
-- Names only (they already appear on the TV and chair cards). Anon-callable
-- because nobody is signed in yet when the list is shown.
create or replace function public.list_login_barbers()
returns table (id uuid, display_name text)
language sql stable security definer set search_path = public as $$
    select s.id, s.display_name
      from public.staff s
      join public.staff_pins p on p.staff_id = s.id
     where s.active and s.role = 'barber'
     order by s.display_name;
$$;

revoke all on function public.list_login_barbers() from public;
grant execute on function public.list_login_barbers() to anon, authenticated;

-- 4. PIN check (barber-login Edge Function only) ----------------------------
-- Returns 'ok' | 'bad' | 'locked' | 'unknown'. 5 wrong PINs lock that barber
-- for 15 minutes. Callable by service_role only.
create or replace function public._verify_barber_pin(p_staff_id uuid, p_pin text)
returns text language plpgsql security definer set search_path = public, extensions as $$
declare
    v_row public.staff_pins;
begin
    select p.* into v_row
      from public.staff_pins p
      join public.staff s on s.id = p.staff_id
     where p.staff_id = p_staff_id and s.active and s.role = 'barber'
     for update of p;
    if not found then
        return 'unknown';
    end if;

    if v_row.locked_until is not null and v_row.locked_until > now() then
        return 'locked';
    end if;

    if p_pin is not null and v_row.pin_hash = crypt(p_pin, v_row.pin_hash) then
        update public.staff_pins set failed_attempts = 0, locked_until = null where staff_id = p_staff_id;
        return 'ok';
    end if;

    update public.staff_pins
       set failed_attempts = case when v_row.failed_attempts + 1 >= 5 then 0 else v_row.failed_attempts + 1 end,
           locked_until    = case when v_row.failed_attempts + 1 >= 5 then now() + interval '15 minutes' else null end
     where staff_id = p_staff_id;
    return case when v_row.failed_attempts + 1 >= 5 then 'locked' else 'bad' end;
end $$;

revoke all on function public._verify_barber_pin(uuid, text) from public, anon, authenticated;
grant execute on function public._verify_barber_pin(uuid, text) to service_role;

-- 5. recovery key: generate (admin) and status ------------------------------
-- 20 characters from a 32-symbol alphabet without look-alikes (~100 bits),
-- shown as XXXXX-XXXXX-XXXXX-XXXXX. Returned once; only the hash is kept.
-- Generating a new key replaces (invalidates) the old one.
create or replace function public.admin_generate_recovery_key()
returns text language plpgsql security definer set search_path = public, extensions as $$
declare
    v_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    v_bytes    bytea := gen_random_bytes(20);
    v_raw      text := '';
    i          integer;
begin
    if not public.is_admin() then
        raise exception 'Not authorised' using errcode = '42501';
    end if;
    for i in 0..19 loop
        v_raw := v_raw || substr(v_alphabet, (get_byte(v_bytes, i) % 32) + 1, 1);
    end loop;

    update public.admin_recovery
       set key_hash = crypt(v_raw, gen_salt('bf', 10)),
           created_at = now(),
           created_by = auth.uid(),
           failed_attempts = 0,
           locked_until = null
     where id;

    return substr(v_raw, 1, 5) || '-' || substr(v_raw, 6, 5) || '-' || substr(v_raw, 11, 5) || '-' || substr(v_raw, 16, 5);
end $$;

revoke all on function public.admin_generate_recovery_key() from public, anon;
grant execute on function public.admin_generate_recovery_key() to authenticated;

create or replace function public.admin_recovery_key_status()
returns table (has_key boolean, created_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
    if not public.is_admin() then
        raise exception 'Not authorised' using errcode = '42501';
    end if;
    return query select r.key_hash is not null, r.created_at from public.admin_recovery r where r.id;
end $$;

revoke all on function public.admin_recovery_key_status() from public, anon;
grant execute on function public.admin_recovery_key_status() to authenticated;

-- 6. recovery: check, then finish (admin-recover Edge Function only) --------
-- Two steps so the key is only spent once the new password is actually set:
--   _check_admin_recovery(key, email) -> the admin's id, or null if refused.
--   _finish_admin_recovery(id)        -> reactivates the admin, spends the key.
-- 5 wrong attempts (any e-mail) lock recovery for 1 hour. A wrong key and an
-- e-mail that is not an admin both just return null, so the endpoint does
-- not reveal which admin e-mails exist.
create or replace function public._check_admin_recovery(p_key text, p_email text)
returns uuid language plpgsql security definer set search_path = public, extensions as $$
declare
    v_rec   public.admin_recovery;
    v_key   text := upper(regexp_replace(coalesce(p_key, ''), '[^A-Za-z0-9]', '', 'g'));
    v_admin uuid;
begin
    select * into v_rec from public.admin_recovery where id for update;

    if v_rec.locked_until is not null and v_rec.locked_until > now() then
        raise exception 'Terlalu banyak cubaan. Cuba lagi selepas 1 jam.' using errcode = '42501';
    end if;
    if v_rec.key_hash is null then
        return null;
    end if;

    select s.id into v_admin
      from public.staff s
      join auth.users u on u.id = s.id
     where s.role = 'admin' and lower(u.email) = lower(btrim(coalesce(p_email, '')));

    if v_admin is null or v_rec.key_hash <> crypt(v_key, v_rec.key_hash) then
        -- Count the failure. Returning (not raising) keeps this update.
        update public.admin_recovery
           set failed_attempts = case when v_rec.failed_attempts + 1 >= 5 then 0 else v_rec.failed_attempts + 1 end,
               locked_until    = case when v_rec.failed_attempts + 1 >= 5 then now() + interval '1 hour' else null end
         where id;
        return null;
    end if;

    update public.admin_recovery set failed_attempts = 0, locked_until = null where id;
    return v_admin;
end $$;

revoke all on function public._check_admin_recovery(text, text) from public, anon, authenticated;
grant execute on function public._check_admin_recovery(text, text) to service_role;

create or replace function public._finish_admin_recovery(p_admin_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
    update public.staff set active = true where id = p_admin_id and role = 'admin';
    update public.admin_recovery
       set key_hash = null, created_at = null, created_by = null, failed_attempts = 0, locked_until = null
     where id;
end $$;

revoke all on function public._finish_admin_recovery(uuid) from public, anon, authenticated;
grant execute on function public._finish_admin_recovery(uuid) to service_role;
